WITH valid AS (SELECT *, INITCAP(TRIM(status)) AS status_title FROM payments WHERE paid_at > TO_TIMESTAMP('2023-06-14 11:00:00')), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), with_windows AS (SELECT id, method, paid_at, island_id, LEAD(is_new_session, 1, 0) OVER (PARTITION BY method ORDER BY paid_at, id) AS next_is_new_session, LAST_VALUE(method) IGNORE NULLS OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_method, AVG(is_new_session) OVER w_ordered AS is_new_session_avg_90d FROM sessionized WHERE status IN ('SUCCESS', 'FAILED') WINDOW w_ordered AS (PARTITION BY status, method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW)), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY method ORDER BY next_is_new_session NULLS LAST, id) AS rn FROM with_windows) t WHERE rn = 1), metrics AS (SELECT *, SUM(is_new_session_avg_90d) OVER (PARTITION BY method ORDER BY is_new_session_avg_90d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_is_new_session_avg_90d, ROW_NUMBER() OVER (PARTITION BY method ORDER BY paid_at DESC, id) AS event_seq FROM ranked) SELECT CASE WHEN event_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END AS event_seq_tier, island_id, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, SUM(cumulative_is_new_session_avg_90d) FILTER (WHERE method = 'paypal') AS paypal_total_cumulative_is_new_session_avg_90d, SUM(island_id) FILTER (WHERE method = 'promptpay') AS promptpay_total_island_id, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN method = 'paypal' THEN 1 END), 0), 2) AS event_seq_per_paypal, SUM(CASE WHEN method = 'card' THEN island_id ELSE 0 END) AS card_island_id, COUNT(*) AS cnt, PERCENT_RANK() OVER (PARTITION BY CASE WHEN event_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END ORDER BY COUNT(*) DESC) AS cnt_percent_rank FROM metrics GROUP BY CASE WHEN event_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END, island_id HAVING span_minutes >= 0 ORDER BY event_seq_tier
